pub open spec fn effective_expiry_spec(lease: Lease) -> u64 {
    if lease.is_revoked {
        min_spec(lease.expiry, lease.revoked_at)
    } else {
        lease.expiry
    }
}

// r[impl lease.effective-expiry]
/// Returns the effective end of this lease, accounting for revocation.
